//! ADR 0058 段 2b: HKDF-SHA-384（`hkdf_extract_sha384`・`hkdf_expand_sha384`）の利用者向けテスト。
//!
//! 出典と検算（ADR 0058 決定 4）:
//! - Extract と Expand の期待値は、独立実装で得た SHA-384 専用ベクタ。RFC 5869 は SHA-384 のベクタを持たないため、
//!   付録 A.1〜A.3 の入力（IKM・salt・info・出力長）を SHA-384 で処理した値を、次の 2 系統で生成して一致を確認した。
//!   (1) Python 標準の `hmac`・`hashlib` による RFC 5869 §2.2・§2.3 の素直な実装（PRK と OKM）、
//!   (2) `cryptography` 50.0.1（OpenSSL）の `HKDF(SHA384)`（OKM）。
//!   追加の入力は、salt が HMAC のブロック長 128 バイトと 129 バイト（鍵を先にハッシュする経路）、空の IKM。
//!   出力長は 1・47・48・49・96・12240（255 × HashLen）の接頭辞を、同じ入力の 12240 バイトの OKM から切り出した。
//! - HMAC-SHA-384 は RFC 4231 §4.2〜§4.8 のテストケース 1・2・3・4・6・7（ケース 5 は出力の切り詰めで対象外）。
//!   値は pyca/cryptography の `vectors/HMAC/rfc-4231-sha384.txt`（SHA-256 `3c51046d16df5af59d699a572cd00005666e7c5b0ca469d118c40737a6748f5d`）から取得し、
//!   `hmac`・`hashlib` で再計算して一致を確認した（rfc-editor.org へはこの環境から到達できない）。
//!   内部の `hmac_any_key_sha384` は公開 API から見えないため、`embedded_extra` で `std.crypto` に試験用の入口を足した版を
//!   評価器で動かして照合する。PRK の値の照合も同じ入口で行う（PRK の型は中身を見せない）。
//! - salt の省略（`None`）は HashLen（48）個のゼロの salt と同じ結果になる（RFC 5869 §2.2）。
//! - 出力長は 0、1、HashLen の前後（47・48・49）、255 × HashLen と、超過（契約違反で異常停止）。
//! - 公開 API のテストは評価器とネイティブの両方で回る（`common::run` が突き合わせる）。

mod common;

use sigil::exec::{Arg, Options, RunError, StopKind};

const HEAD: &str = "module crypto_hkdf_sha384.t\n  targets server\n  trust none\n\n";

const MISMATCH_FN: &str = "fn mismatch(d: &Bytes, want: &List<Int>) -> Int\n  intent \"x\"\n  requires none\n  ensures none\n  effects none\n{\n  let mut bad = 0;\n  let mut i = 0;\n  while i < want.len() {\n    let w = match want.get(i) { Some(v) => v, None => 0 };\n    let g = d.get(i).unwrap_or(0 - 1);\n    if g != w {\n      bad = bad + 1;\n    }\n    i = i + 1;\n  }\n  if d.byte_len() != want.len() {\n    bad = bad + 100;\n  }\n  return bad;\n}\n\n";

const MAIN_HEAD: &str =
    "fn main() -> Int\n  intent \"x\"\n  requires none\n  ensures none\n  effects none\n{\n";

fn unhex(h: &str) -> Vec<u8> {
    (0..h.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&h[i..i + 2], 16).unwrap())
        .collect()
}

fn build_bytes(name: &str, bytes: &[u8]) -> String {
    let mut s = format!("  let mut {name} = Bytes.new();\n");
    for b in bytes {
        s.push_str(&format!("  {name}.push({b});\n"));
    }
    s
}

fn build_expected(name: &str, hex: &str) -> String {
    let mut s = format!("  let mut {name} = List.new();\n");
    for b in unhex(hex) {
        s.push_str(&format!("  {name}.push({b});\n"));
    }
    s
}

