const A1_NONE_OKM: &str =
    "c8c96e710f89b0d7990bca68bcdec8cf854062e54c73a7abc743fade9b242daacc1cea5670415b52849c";

enum Salt<'a> {
    Omitted,
    Given(&'a [u8]),
}

fn run_okm(salt: &Salt, ikm: &[u8], info: &[u8], out_len: i64, expected_hex: &str) -> i64 {
    let (ssrc, sarg) = match salt {
        Salt::Omitted => (String::new(), "None".to_string()),
        Salt::Given(b) => (
            format!(
                "{}  let salt = Secret.from_bytes(sb);\n",
                build_bytes("sb", b)
            ),
            "Some(salt)".to_string(),
        ),
    };
    let src = format!(
        "{HEAD}{MISMATCH_FN}{MAIN_HEAD}{ssrc}{}  let ikm_s = Secret.from_bytes(ib);\n{}  let prk = hkdf_extract_sha384({sarg}, &ikm_s);\n{}  let okm = hkdf_expand_sha384(&prk, &info, {out_len});\n  let got = okm.expose();\n  return mismatch(&got, &want);\n}}\n",
        build_bytes("ib", ikm),
        build_bytes("info", info),
        build_expected("want", expected_hex),
    );
    let r = common::run(&src, "main", &[] as &[Arg]).unwrap();
    r.value.parse().unwrap()
}

#[test]
fn hkdf_sha384_independent_vectors() {
    for (name, salt, ikm, info, out_len, _prk, okm) in HKDF384 {
        let r = run_okm(
            &Salt::Given(&unhex(salt)),
            &unhex(ikm),
            &unhex(info),
            *out_len,
            okm,
        );
        assert_eq!(r, 0, "{name}");
    }
}

#[test]
fn hkdf_sha384_omitted_salt_equals_hashlen_zero_salt() {
    // RFC 5869 §2.2: salt 省略は HashLen（48）個のゼロ。A1 の IKM で、省略・48 個のゼロ・空の salt が同じ OKM になる。
    let a1 = HKDF384.iter().find(|c| c.0 == "A1").unwrap();
    let ikm = unhex(a1.2);
    assert_eq!(run_okm(&Salt::Omitted, &ikm, &[], 42, A1_NONE_OKM), 0);
    assert_eq!(
        run_okm(&Salt::Given(&[0u8; 48]), &ikm, &[], 42, A1_NONE_OKM),
        0
    );
    assert_eq!(run_okm(&Salt::Given(&[]), &ikm, &[], 42, A1_NONE_OKM), 0);
}

/// `A1` の入力で出力長 `out_len` の OKM を作り、長さと、`want_prefix` との接頭辞の一致数を返す。
fn run_len(out_len: i64, want_prefix: &[u8]) -> (i64, i64) {
    let a1 = HKDF384.iter().find(|c| c.0 == "A1").unwrap();
    let src = format!(
        "{HEAD}{MAIN_HEAD}{}{}{}{}  let salt = Secret.from_bytes(sb);\n  let ikm = Secret.from_bytes(ib);\n  let prk = hkdf_extract_sha384(Some(salt), &ikm);\n  let okm = hkdf_expand_sha384(&prk, &info, {out_len});\n  let got = okm.expose();\n  let mut bad = 0;\n  let mut i = 0;\n  while i < got.byte_len() && i < pre.byte_len() {{\n    if got.get(i).unwrap_or(0 - 1) != pre.get(i).unwrap_or(0 - 2) {{\n      bad = bad + 1;\n    }}\n    i = i + 1;\n  }}\n  return got.byte_len() * 1000 + bad;\n}}\n",
        build_bytes("sb", &unhex(a1.1)),
        build_bytes("ib", &unhex(a1.2)),
        build_bytes("info", &unhex(a1.3)),
        build_bytes("pre", want_prefix),
    );
    let r = common::run(&src, "main", &[] as &[Arg]).unwrap();
    let v: i64 = r.value.parse().unwrap();
    (v / 1000, v % 1000)
}

#[test]
fn hkdf_sha384_expand_output_lengths() {
    let (len, bad) = run_len(0, &[]);
    assert_eq!((len, bad), (0, 0));
    for (n, hex) in A1_PREFIXES {
        let (len, bad) = run_len(*n as i64, &unhex(hex));
        assert_eq!(len, *n as i64, "out_len={n}");
        assert_eq!(bad, 0, "out_len={n} 接頭辞の不一致");
    }
}

#[test]
fn hkdf_sha384_expand_max_length_255_blocks() {
    // 255 × 48 = 12240 バイト。長さと、末尾 96 バイト（最後の 2 ブロック）の一致を確かめる。
    let a1 = HKDF384.iter().find(|c| c.0 == "A1").unwrap();
    let tail = unhex(A1_TAIL_96);
    let src = format!(
        "{HEAD}{MAIN_HEAD}{}{}{}{}  let salt = Secret.from_bytes(sb);\n  let ikm = Secret.from_bytes(ib);\n  let prk = hkdf_extract_sha384(Some(salt), &ikm);\n  let okm = hkdf_expand_sha384(&prk, &info, 12240);\n  let got = okm.expose();\n  let mut bad = 0;\n  let mut i = 0;\n  while i < 96 {{\n    if got.get(12144 + i).unwrap_or(0 - 1) != tail.get(i).unwrap_or(0 - 2) {{\n      bad = bad + 1;\n    }}\n    i = i + 1;\n  }}\n  return got.byte_len() * 1000 + bad;\n}}\n",
        build_bytes("sb", &unhex(a1.1)),
        build_bytes("ib", &unhex(a1.2)),
        build_bytes("info", &unhex(a1.3)),
        build_bytes("tail", &tail),
    );
    let r = common::run(&src, "main", &[] as &[Arg]).unwrap();
    assert_eq!(r.value, "12240000");
}

fn stop_kind(src: &str) -> StopKind {
    match common::run(src, "main", &[] as &[Arg]) {
        Ok(o) => panic!("異常停止するはずが成功した: {}", o.value),
        Err(e) => match e.error {
            RunError::Stop(s) => s.kind,
            other => panic!("異常停止でない失敗: {other}"),
        },
    }
}

fn over_limit_src(len_expr: &str) -> String {
    let a1 = HKDF384.iter().find(|c| c.0 == "A1").unwrap();
    format!(
        "{HEAD}{MAIN_HEAD}{}  let ikm = Secret.from_bytes(ib);\n  let prk = hkdf_extract_sha384(None, &ikm);\n  let info = Bytes.new();\n  let okm = hkdf_expand_sha384(&prk, &info, {len_expr});\n  return okm.byte_len();\n}}\n",
        build_bytes("ib", &unhex(a1.2)),
    )
}

#[test]
fn hkdf_sha384_expand_over_limit_is_requires_violation() {
    assert_eq!(
        stop_kind(&over_limit_src("12241")),
        StopKind::RequiresViolated
    );
}

#[test]
fn hkdf_sha384_expand_negative_length_is_requires_violation() {
    assert_eq!(
        stop_kind(&over_limit_src("0 - 1")),
        StopKind::RequiresViolated
    );
}

// ---------------------------------------------------------------------------
// 内部の HMAC-SHA-384（RFC 4231）と PRK: `embedded_extra` の試験用入口（評価器）
// ---------------------------------------------------------------------------

fn internal_probe() -> String {
    let mut s = String::new();
    s.push_str("pub fn internal_probe() -> Int\n  intent \"RFC 4231 と PRK を照合する\"\n  requires none\n  ensures none\n  effects none\n{\n  let mut bad = 0;\n");
    for (i, (_n, k, m, d)) in RFC4231.iter().enumerate() {
        s.push_str(&build_bytes(&format!("hk{i}"), &unhex(k)));
        s.push_str(&build_bytes(&format!("hm{i}"), &unhex(m)));
        s.push_str(&build_expected(&format!("hw{i}"), d));
        s.push_str(&format!(
            "  let ho{i} = hmac_any_key_sha384(&hk{i}, &hm{i});\n  bad = bad + mismatch(&ho{i}, &hw{i});\n"
        ));
    }
    for (i, (_n, salt, ikm, _info, _len, prk, _okm)) in HKDF384.iter().enumerate() {
        s.push_str(&build_bytes(&format!("ps{i}"), &unhex(salt)));
        s.push_str(&build_bytes(&format!("pi{i}"), &unhex(ikm)));
        s.push_str(&build_expected(&format!("pw{i}"), prk));
        s.push_str(&format!(
            "  let psec{i} = Secret.from_bytes(ps{i});\n  let isec{i} = Secret.from_bytes(pi{i});\n  let pp{i} = hkdf_extract_sha384(Some(psec{i}), &isec{i});\n  let pg{i} = pp{i}.key.expose();\n  bad = bad + mismatch(&pg{i}, &pw{i});\n"
        ));
    }
    s.push_str("  return bad;\n}\n");
    s
}

#[test]
fn hmac_sha384_rfc4231_and_hkdf_prk_match_on_the_internal_functions() {
    let module = format!(
        "{}\n{}\n{}",
        include_str!("../src/stdlib/crypto.sigil"),
        MISMATCH_FN,
        internal_probe()
    );
    let entry = format!("{HEAD}pub fn main() -> Int\n  intent \"x\"\n  requires none\n  ensures none\n  effects none\n{{\n  return 7;\n}}\n");
    let o = Options {
        embedded_extra: vec![("std.crypto".to_string(), module)],
        embedded_roots: vec!["std.crypto".into()],
        ..Options::captured()
    };
    let r = sigil::ir_eval::run_sources_with(&[&entry], "std.crypto.internal_probe", &[], &o)
        .unwrap_or_else(|f| panic!("{:?}", f.error));
    assert_eq!(r.value, "0");
}
